preConditionHook:
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and thereafter updated as
// TWO statements -- EL evaluates S[1] + in - out left to right, and folding it
// to S += in - out rounds differently (@OJ 2015-02-20).
// The local counter is atrLen, not atrLength: atrLength is this rule's INPUT.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
// The highest high and lowest low over lookback bars, the window INCLUSIVE of the
// current bar. Mirrors EL Extremes(), which the highest/lowest words both call: seeded
// at bar 0, scanning bars 1..Length-1, strict comparison so a tie keeps the
// earliest bar. Extremes is EL SOURCE, so its comparisons carry the relational
// tolerance -- el_gt/el_lt, not > and < (see Breakout).
hh = high[0];
ll = low[0];
for (int i = 1; i < (int)lookback; ++i) {
    if (el_gt(high[i], hh)) hh = high[i];
    if (el_lt(low[i], ll)) ll = low[i];
}
